contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address caller1, address caller2, address logAddr) public {
        if (caller1 == address(0)) caller1 = address(0x1234);
        if (caller2 == address(0)) caller2 = address(0x2345);
        if (logAddr == address(0)) logAddr = address(0x3456);

        bool ok1;
        try c.SetLogFile(logAddr) {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        bool ok2;
        vm.prank(caller2);
        try c.SetLogFile(logAddr) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(ok1 && ok2);
    }
}
